import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BqDA2HS7.js";const u=JSON.parse('{"title":"六种策略概览","description":"","frontmatter":{},"headers":[],"relativePath":"strategies/index.md","filePath":"strategies/index.md"}'),s={name:"strategies/index.md"};function o(i,t,l,h,n,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="六种策略概览" tabindex="-1">六种策略概览 <a class="header-anchor" href="#六种策略概览" aria-label="Permalink to &quot;六种策略概览&quot;">​</a></h1><p>先明确什么结果算合格，再选择需要的路由行为。增加 Judge 或切换模型可能提高费用与等待时间， 并不自动提高质量。</p><h2 id="按需求选择" tabindex="-1">按需求选择 <a class="header-anchor" href="#按需求选择" aria-label="Permalink to &quot;按需求选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你希望的行为</th><th>策略</th><th>需要额外 Judge 吗？</th></tr></thead><tbody><tr><td>固定一个模型，验证接线</td><td><a href="./static.html">Static</a></td><td>不需要</td></tr><tr><td>依据工具证据临时换模</td><td><a href="./stage.html">Stage</a></td><td>默认规则模式不需要；协作模式可选 Jev／Laya</td></tr><tr><td>每个任务从池中选一个主模型</td><td><a href="./task.html">Task</a></td><td>多个合格候选时一次；单候选跳过</td></tr><tr><td>Task 初选后仍能临时接管</td><td><a href="./composite.html">Composite</a></td><td>Task 一次；后续规则默认不调用</td></tr><tr><td>最终答案审核后才交付，允许返工</td><td><a href="./advisor.html">Advisor Gate</a></td><td>最多两次审核</td></tr><tr><td>起始模型不合适时由指定模型接手</td><td><a href="./escalation.html">Escalation</a></td><td>接管前逐份起始候选检查；接管后停止 Judge</td></tr></tbody></table><h2 id="审核与接管的区别" tabindex="-1">审核与接管的区别 <a class="header-anchor" href="#审核与接管的区别" aria-label="Permalink to &quot;审核与接管的区别&quot;">​</a></h2><ul><li><strong>Advisor</strong>：保持同一执行器，发现问题时要求它返工，复审通过才交付。</li><li><strong>Escalation</strong>：丢弃起始候选，由接管模型生成；接管后任务内锁定，未追加审核。</li><li><strong>Stage</strong>：根据执行轨迹决定下一轮用谁，保持结束后可恢复。</li><li><strong>Task</strong>：任务开始选一次，工具续接不重新选。</li></ul><h2 id="费用如何看" tabindex="-1">费用如何看 <a class="header-anchor" href="#费用如何看" aria-label="Permalink to &quot;费用如何看&quot;">​</a></h2><p>比较全部实际调用：执行、Task Judge、逐轮判别、审核、返工、接管和失败尝试。 订阅路线的参考估值与按量现金分别记录，不将两列相加。 同名模型、较高价格或“强执行”角色标签均不证明实际能力更强。</p><h2 id="实验标识" tabindex="-1">实验标识 <a class="header-anchor" href="#实验标识" aria-label="Permalink to &quot;实验标识&quot;">​</a></h2><p>规则＋Jev／Laya 的 Stage 判别、当前本地 Laya 的各用途质量，以及 Jev 的分动作门槛 保留明确实验标识。接线可运行不代表自然任务误放行或误升级率已经达标。 当前开放任务收益与媒体、子 Agent 共享预算的边界见<a href="./../status.html">验证范围</a>。</p>',10)])])}const g=a(s,[["render",o]]);export{u as __pageData,g as default};
